    alphaPowerHelp: "α（Alpha）波通常在放松、闭眼时增强，频率 8–13 Hz，枕叶最明显。Alpha 波功率增加一般反映放松程度提高。",
    gammaPowerHelp: "γ（Gamma）波是最快的脑电节律（30–100 Hz），与主动认知处理、注意聚焦相关，但极易混入肌电伪迹，需高采样率（≥500 Hz）才能可靠记录。",
    betaPowerHelp: "β（Beta）波与主动思考、注意力集中相关，频率 13–30 Hz，额叶区域明显。Beta 波功率反映认知活跃程度。",
    thetaPowerHelp: "θ（Theta）波在轻度困倦、冥想或记忆检索时出现，频率 4–8 Hz。Theta 波功率增加可能与创造力或浅睡眠有关。",
    deltaPowerHelp: "δ（Delta）波是深度睡眠的标志，频率 0.5–4 Hz，在整个大脑皮层弥散分布。Delta 波功率高表示进入了深度修复性睡眠。",
    alphaFreqHelp: "Alpha 波的峰值频率通常在 9–11 Hz 之间，随年龄和认知状态变化。频率偏移（如低于 8 Hz）可能提示神经功能变化。",
    betaFreqHelp: "Beta 波涵盖较宽频率范围（13–30 Hz）。低 Beta（13–20 Hz）与平静专注相关，高 Beta（20–30 Hz）与高度警觉或焦虑相关。",
    thetaFreqHelp: "Theta 波频率范围 4–8 Hz。4–6 Hz 在深度冥想中常见，6–8 Hz 在创造性思维或记忆编码时出现。",
    deltaFreqHelp: "Delta 波频率 0.5–4 Hz，是最慢的脑电节律。大脑在深度睡眠时产生大量 Delta 波，对记忆巩固和身体修复至关重要。",
    gammaFreqHelp: "γ 波峰值频率通常在 30–100 Hz 之间可调；注意采样率须 ≥2 倍目标频率（奈奎斯特定理）。",
    noiseHelp: "噪声水平模拟 EEG 信号中的背景噪声和干扰。实际 EEG 中噪声可能来自电极接触不良、肌肉活动或环境电磁干扰。",

    artifactBlinkHelp: "眨眼伪影由眼球运动（尤其是眨眼时角膜-视网膜电位变化）产生，在额叶电极（Fp1/Fp2）最为明显，表现为大幅垂直偏转。实际 EEG 分析中通常通过 ICA 或阈值法去除。",
    artifactMuscleHelp: "肌电伪影（EMG）由颞肌或额肌收缩产生，频率范围广（20–300+ Hz），在颞叶电极（T3/T4）最明显。高密度高频活动是其主要特征。",
    artifactPowerlineHelp: "工频干扰（50Hz/60Hz）由电力系统电磁场耦合到 EEG 信号中产生，表现为所有通道一致的 50Hz 正弦波噪声。实际中通过陷波滤波器（Notch Filter）去除。",
