    alphaPowerHelp: "Alpha (α) waves are typically enhanced when relaxed with eyes closed, 8–13 Hz, most prominent in occipital lobe. Higher alpha power generally indicates greater relaxation.",
    gammaPowerHelp: "Gamma (γ) waves are the fastest brainwave rhythm (30–100 Hz), linked to active cognitive processing and focused attention, but easily contaminated by muscle artifacts; sampling rates ≥500 Hz are needed for reliable recording.",
    betaPowerHelp: "Beta (β) waves are associated with active thinking and focused attention, 13–30 Hz, prominent in frontal regions. Beta power reflects cognitive engagement.",
    thetaPowerHelp: "Theta (θ) waves appear during light drowsiness, meditation, or memory retrieval, 4–8 Hz. Increased theta power may relate to creativity or light sleep.",
    deltaPowerHelp: "Delta (δ) waves are markers of deep sleep, 0.5–4 Hz, diffused across the cortex. High delta power indicates deep restorative sleep.",
    alphaFreqHelp: "Alpha peak frequency is typically between 9–11 Hz, varying with age and cognitive state. Frequency shift (e.g. below 8 Hz) may indicate neurological changes.",
    betaFreqHelp: "Beta spans a wide range (13–30 Hz). Low beta (13–20 Hz) relates to calm focus, high beta (20–30 Hz) to hyper-alertness or anxiety.",
    thetaFreqHelp: "Theta frequency range is 4–8 Hz. The 4–6 Hz band is common in deep meditation; 6–8 Hz appears during creative thinking or memory encoding.",
    deltaFreqHelp: "Delta waves at 0.5–4 Hz are the slowest brain rhythm. The brain generates abundant delta during deep sleep, essential for memory consolidation and recovery.",
    gammaFreqHelp: "γ peak frequency is adjustable between 30–100 Hz; sampling rate must be ≥2× the target frequency (Nyquist theorem).",
    noiseHelp: "Noise level simulates background noise and interference in EEG signals. In real EEG, noise can come from poor electrode contact, muscle activity, or electromagnetic interference.",

    artifactBlinkHelp: "Blink artifacts arise from eye movements (corneo-retinal potential changes during blinking), most prominent in frontal electrodes (Fp1/Fp2) as large vertical deflections. Typically removed via ICA or thresholding in real EEG analysis.",
    artifactMuscleHelp: "EMG (muscle) artifacts are caused by temporal or frontal muscle contraction, with a wide frequency range (20–300+ Hz), most visible in temporal electrodes (T3/T4). Characterized by high-density high-frequency activity.",
    artifactPowerlineHelp: "Powerline interference (50Hz/60Hz) is caused by electromagnetic coupling from the power grid into EEG signals, appearing as consistent 50Hz sine wave noise across all channels. Removed via notch filter in practice.",
