    eegSimulator: "Simulador EEG",
    eegSimulatorDesc: "Ajusta parámetros para generar señales EEG sintéticas y observar diferentes estados cerebrales",

    alphaPowerHelp: "Las ondas Alpha (α) suelen aumentar en relajación con ojos cerrados, 8-13 Hz, más prominentes en lóbulo occipital. Mayor potencia alfa indica mayor relajación.",
    gammaPowerHelp: "Las ondas Gamma (γ) son el ritmo cerebral más rápido (30–100 Hz), vinculado al procesamiento cognitivo activo y la atención, pero fácilmente contaminadas por artefactos musculares; se necesitan ≥500 Hz de muestreo.",
    betaPowerHelp: "Las ondas Beta (β) se asocian con pensamiento activo y atención concentrada, 13-30 Hz, prominentes en regiones frontales. Refleja compromiso cognitivo.",
    thetaPowerHelp: "Las ondas Theta (θ) aparecen durante somnolencia ligera, meditación o recuperación de memoria, 4-8 Hz. Puede relacionarse con creatividad o sueño ligero.",
    deltaPowerHelp: "Las ondas Delta (δ) son marcadores de sueño profundo, 0.5-4 Hz, difundidas por la corteza. Alta potencia delta indica sueño reparador.",
    alphaFreqHelp: "La frecuencia pico alfa suele estar entre 9-11 Hz, varía con edad y estado cognitivo. Desplazamiento (>8 Hz) puede indicar cambios neurológicos.",
    betaFreqHelp: "Beta abarca un rango amplio (13-30 Hz). Beta baja (13-20 Hz) = concentración calmada; beta alta (20-30 Hz) = hipervigilancia o ansiedad.",
    thetaFreqHelp: "Rango theta: 4-8 Hz. 4-6 Hz común en meditación profunda; 6-8 Hz durante pensamiento creativo o codificación de memoria.",
    deltaFreqHelp: "Delta: 0.5-4 Hz, el ritmo cerebral más lento. El cerebro genera abundante delta en sueño profundo, esencial para consolidación de memoria y recuperación.",
    gammaFreqHelp: "La frecuencia pico de γ es ajustable entre 30–100 Hz; la tasa de muestreo debe ser ≥2× la frecuencia objetivo (teorema de Nyquist).",
    noiseHelp: "Nivel de ruido simula ruido de fondo en señales EEG. En EEG real, puede deberse a mal contacto de electrodos, actividad muscular o interferencia electromagnética.",

    artifactBlinkHelp: "Los artefactos de parpadeo surgen del movimiento ocular (cambios de potencial córneo-retinal al parpadear), más prominentes en electrodos frontales (Fp1/Fp2). Se eliminan mediante ICA o umbralización.",
    artifactMuscleHelp: "Los artefactos EMG (musculares) provienen de contracción muscular temporal o frontal, rango 20-300+ Hz, visibles en electrodos temporales (T3/T4). Actividad de alta frecuencia y densidad.",
    artifactPowerlineHelp: "Interferencia de red (50Hz/60Hz) por acoplamiento electromagnético de la red eléctrica en EEG, ruido sinusoidal de 50Hz en todos los canales. Eliminado con filtro notch.",
