    disclaimerGuide: "NeuroAccess est une plateforme éducative d'alphabétisation EEG conçue pour aider les personnes ordinaires à comprendre les données EEG. Nous ne sommes pas une institution médicale et ne fournissons pas de services de diagnostic. L'interprétation de l'EEG nécessite une formation professionelle. Si vous avez des préoccupations de santé, veuillez consulter un médecin professionel. Toutes les explications dans ce rapport sont générées par des modèles d'IA locaux uniquement à des fins éducatives.",

