    guideThetaDesc: "Les ondes theta sont associées à la méditation, au sommeil léger et à l’encodage de la mémoire. Elles sont plus courantes chez les enfants/adolescents ; une excès d’ondes theta chez un adulte en veille peut indiquer une anomalie.",
    guideThetaTitle: "Ondes Theta (θ)",
    guideThetaWhat: "Les ondes theta varient entre 4 et 8 Hz, avec une amplitude moyenne à élevée (20 à 100 μV), distribuées principalement dans les régions frontales et temporaire. Elles sont particulièrement prononcées lors de la transition du sommeil et pendant le sommeil REM.",
    guideThetaWhy: "Les ondes theta participent à la consolidation de la mémoire et à la navigation spatiale. Le rythme theta hippocampien joue un rôle clé dans l’apprentissage. Cliniquement, une theta généralisée peut être observée dans certaines pathologies cérébrales nécessitant une évaluation médicale.",

