    // Disclaimer Modal
    disclaimerModalTitle: "Haftungsausschluss",
    disclaimerModalSubtitle: "Bitte lesen Sie sorgfaltig vor der Nutzung von NeuroAccess",
    disclaimerImportant: "Wichtiger Hinweis:",
    disclaimerPoint1: "NeuroAccess ist eine EEG-Bildungsplattform, die Benutzern hilft, EEG-Daten zu verstehen. Sie stellt keine medizinische Diagnose, Beratung oder Behandlung dar.",
    disclaimerPoint2: "Die professionelle Interpretation von EEG-Daten erfordert qualifizierte medizinische Fachkrafte mit vollstandigem klinischem Kontext.",
    disclaimerPoint3: "Diese Plattform kann und diagnostiziert keine Krankheit, keinen Geisteszustand, keine Intelligenzstufe, keine Personlichkeitseigenschaft und kein Gesundheitsrisiko.",
    disclaimerPoint4: "Alle Analyseergebnisse und KI-Erklarungen dienen nur zu Bildungszwecken und sollten nicht als Grundlage fur medizinische Entscheidungen verwendet werden.",
    disclaimerPoint5: "Wenn Sie gesundheitliche Bedenken haben, konsultieren Sie bitte einen professionellen Arzt.",
    disclaimerPoint6: "Hochgeladene EEG-Dateien werden nur fur die Echtzeitanalyse verwendet und nicht langfristig gespeichert oder fur andere Zwecke genutzt.",
    disclaimerAgreement: 'Durch Klicken auf "Ich verstehe und stimme zu" erkennen Sie die obigen Bedingungen an und stimmen ihnen zu.',
