    correctAnswer: "Richtige Antwort",
    guideDeltaWhat: "Delta-Wellen liegen im Bereich von 0,5–4 Hz, haben eine hohe Amplitude (100–200 μV) und verteilen sich weitverbreitet. Sie sind Merkmal des NREM-Stadiums 3 (langwelligen Schlaf). Lokale Delta-Aktivität bei erwachenden Zuständen kann Strukturelle Hirnveränderungen anzeigen.",
    guideDeltaWhy: "Delta ist entscheidend für die Bewertung der Schlafqualität und Tiefe. Die langwellige Aktivität während des tiefen Schlafs wird für die Gedächtnis-Konsolidierung und Hirn-Restaurierung als notwendig angesehen.",
    guideDisclaimer: "Haftungsausschluss: Alle obigen Wissenskarten dienen ausschließlich zum Zweck der EEG-Bildung. Sie stellen keine medizinische Beratung, Diagnose oder Behandlungsanweisungen dar. EEG-Daten allein können keine Krankheit diagnostizieren. Bei gesundheitlichen Bedenken wenden Sie sich bitte an einen qualifizierten Arzt.",
    guideEmptyState: "Keine passenden Wissenskarten gefunden",
    guideNoiseCannotTell: "Es gibt kein absolut 'reines' EEG. Alle EEG enthalten ein gewisses Rauschen. SNR-Werte können nicht direkt verglichen werden über verschiedene Geräte.",
    guideNoiseDesc: "EEG hat intrinsisch ein niedriges Signal-Rauschverhältnis. Umgebungs-RF-Rausch, Elektrodenimpedanz und physiologische Artfakte beeinflussen die Datengüte.",
    guideNoiseTitle: "Signal-Rauschverhältnis & SNR",
    guideNoiseWhat: "SNR = Signalleistung / Rauschleistung. Die EEG-Amplitude beträgt typischerweise 10–100 μV. Rauschquellen sind: 50/60 Hz Stromkreisinterferenz, Kontakt-Rausch zwischen Elektroden und Haut, Bewegung des Subjekts usw.",
    guideNoiseWhy: "Ein niedriges SNR macht Frequenz-, ERP- und Zusammenhangsanalysen unzuverlässig. Möglichkeiten zur Verbesserung des SNR sind: niedrige Impedanz (<5 kΩ), verschlossene Umgebung, Bandpassfilterung (0,5–40 Hz), Signal-Durchschnittsbildung.",
    guidePsdCannotTell: "PSD kann keine transiente Ereignisse (Spikes, ERPs) erkennen. PSD ist eine durchschnittliche Maßzahl und kann die zeitlichen Dynamiken des Signals nicht widerspiegeln.",
    guidePsdDesc: "PSD ist das Kernwerkzeug für die Frequenzbereichsanalyse des EEG, das die Leistungsverteilung über Frequenzen quantifiziert.",
    guidePsdTitle: "Leistungsspektrale Dichte (PSD)",
    guidePsdWhat: "PSD transformiert zeitliche EEG-Daten in den Frequenzbereich durch Fourier-Transformation (häufig Welch-Methode). Einheiten: μV²/Hz oder dB. Wird weitgehend in Schlaf- und kognitiven Forschungen verwendet.",
    guidePsdWhy: "PSD ermöglicht die Quantifizierung der Bandenergie (Bandpower), die Identifikation dominanter Rhythmen und die Vergleichbarkeit von spektralen Unterschieden unter verschiedenen Bedingungen/Gruppen. Grundlage für Zusammenhangsanalysen und Zeit-Frequenz-Analysen.",
    guideSamplingCannotTell: "Eine hohe Samplingrate kann nicht für schlechte Signalqualität kompensieren. Eine Samplingrate >1000 Hz bietet für die Routine-EEG-Analyse keinen zusätzlichen Vorteil.",
    guideSamplingDesc: "Die Samplingrate bestimmt die zeitliche Auflösung des EEG. Nach dem Satz von Nyquist muss sie mindestens 2-fach der höchsten interessierenden Frequenz betragen.",
    guideSamplingTitle: "Samplingrate",
    guideSamplingWhat: "Die Samplingrate wird in Hz gemessen, häufige Werte sind: 128/256/500/1000 Hz. 250 Hz bedeutet, dass es 250 Datenpunkte pro Sekunde gibt. Die Nyquist-Frequenz beträgt Samplingrate / 2, die höchste analysierbare Frequenz.",
    guideSamplingWhy: "Eine zu geringe Samplingrate kann Aliasing verursachen, bei dem hohe Frequenzen als niedrige Frequenzen maskiert werden. Für standardmäßiges EEG (<40 Hz) ist eine Samplingrate von 128 Hz ausreichend, aber das Studium von Gamma (>50 Hz) erfordert eine Samplingrate von mindestens 250 Hz.",
    guideSearchPlaceholder: "Suche nach Wissenskarten...",
    guideAlphaFrequency: "8 – 12 Hz",
    guideAlphaRanges: "8 – 12 Hz, okzipital dominant",
    guideBetaFrequency: "12 – 30 Hz",
    guideBetaRanges: "12 – 30 Hz, frontozentral dominant",
    guideThetaFrequency: "4 – 8 Hz",
    guideThetaRanges: "4 – 8 Hz, frontotemporal dominant",
    guideDeltaFrequency: "0,5 – 4 Hz",
    guideDeltaRanges: "0,5 – 4 Hz, weitverbreitet",
    guideGammaFrequency: "30 – 100 Hz",
    guideGammaRanges: "30 – 100 Hz, Abtastung ≥500 Hz erforderlich",
    guideChannelsRanges: "Standard: 19–21 (klinisch), 32–256 (Forschung)",
    guideSamplingRanges: "Klinisch: 128–256 Hz; Forschung: 250–1000+ Hz",
    guidePsdRanges: "Typische Auflösung: 0,5–2 Hz bins, analysiert 0,5–40 Hz",
    guideBandpowerRanges: "Delta: 0,5–4 Hz; Theta: 4–8 Hz; Alpha: 8–12 Hz; Beta: 12–30 Hz",
    guidePageSubtitle: "Interaktive EEG-Wissenskarten · Klicken zum Erweitern",
    guideThetaCannotTell: "Theta kann keine ADHD (obwohl Hypothesen über Theta/Beta-Verhältnis bestehen), Meditationstiefe, Gedächtnisqualität oder Hirnerkrankungen diagnostizieren.",
    guideThetaDesc: "Theta-Wellen sind mit Meditation, leichtem Schlaf und Gedächtniscodezision verbunden. Sie sind häufiger bei Kindern/Jugendlichen zu finden; eine übermäßige Theta-Aktivität bei erwachenden Erwachsenen kann eine Abnormität anzeigen.",
    guideThetaTitle: "Theta-Wellen (θ)",
    guideThetaWhat: "Theta-Wellen liegen im Bereich von 4–8 Hz, haben eine mittlere bis hohe Amplitude (20–100 μV) und verteilen sich vor allem in vorderen und temporaeren Regionen. Sie sind besonders während des Schlafwechsels und REM-Schlafes prominent.",
    guideThetaWhy: "Theta nimmt an der Gedächtnis-Konsolidierung und räumlichen Navigation teil. Der hippocampusbasierte Theta-Rhythmus spielt eine Schlüsselrolle bei der Lernprozess. Klinisch gesehen kann diffuse Theta bei bestimmten Enzephalopathien zu sehen sein, was eine ärztliche Bewertung erfordert.",

