/**
 * 获取翻译文本（兼容 language-context.tsx 的导入）
 */
export function getText(lang: Lang, key: string): string {
  return translations[lang]?.[key] ?? key;
}

/**
 * 更简洁的调用方式：t(lang, key)
 */
export function t(lang: Lang, key: string): string {
  return translations[lang]?.[key] ?? key;
}
